sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    try {
        gs.info("🚀 Business Rule triggered for incident: " + current.number);

        // Build the input text safely
        var shortDesc = current.short_description ? current.short_description.toString() : "";
        var desc = current.description ? current.description.toString() : "";
        var inputText = (shortDesc + " " + desc).trim();

        if (!inputText) {
            gs.warn("⚠️ No text to classify.");
            return;
        }

        // Candidate labels for your incident categories
        var candidateLabels = [
            "Network",
            "Hardware",
            "Software",
            "Email",
            "Access",
            "Security"
        ];

        // Create the JSON body
        var bodyObj = {
            "inputs": inputText,
            "parameters": {
                "candidate_labels": candidateLabels
            }
        };

        var bodyStr = JSON.stringify(bodyObj);
        gs.info("📦 Sending body: " + bodyStr);

        // REST call
        var r = new sn_ws.RESTMessageV2();
        r.setHttpMethod("post");
        r.setEndpoint("https://api-inference.huggingface.co/models/typeform/distilbert-base-uncased-mnli");
        r.setRequestHeader("Authorization", "Bearer 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");
        r.setRequestHeader("Content-Type", "application/json");
        r.setRequestBody(bodyStr);

        var response = r.execute();
        var status = response.getStatusCode();
        var responseBody = response.getBody();

        gs.info("📡 HTTP Status: " + status);
        gs.info("🧠 Response: " + responseBody);

        if (status != 200) {
            gs.error("❌ Hugging Face API error: " + responseBody);
            return;
        }

        var result = JSON.parse(responseBody);

        gs.info("🧠 result: " + result);

        if (result && result.labels && result.scores) {
            var topLabel = result.labels[0];
            var confidence = result.scores[0];

            current.ai_category = topLabel + " (" + confidence.toFixed(2) + ")";
            current.setWorkflow(false);
            current.update();

            gs.info("✅ Categorized as: " + topLabel + " (" + confidence.toFixed(2) + ")");
        }

    } catch (e) {
        gs.error("💥 Exception: " + e.message);
    }


    /*
