      // log basics
      var conf = 0;
      var topLabel = null;
      if (result && result.body && result.body.labels && result.body.scores) {
        topLabel = result.body.labels[0];
        conf = parseFloat(result.body.scores[0]) || 0;
      }

      // insert log
      var log = new GlideRecord('x_1259673_intell_0_ai_classification_log');
      log.initialize();
      log.incident = current.sys_id;
      log.request = JSON.stringify({ text: text, candidates: candidateLabels });
      log.response = JSON.stringify(result.body);
      log.label = topLabel;
      log.confidence = conf;
      log.status = result.status;
      log.insert();

      var CONF_THRESHOLD = 0.75;
      if (conf >= CONF_THRESHOLD && topLabel) {
        var map = ai.mapLabelToSN(topLabel);
        if (map && map.category_sys_id) {
          // update incident (note: current is async; updating safely)
